package it.neckar.open.generated

/**
 * The marker of ADL 0180, for the first lines of a generated file:
 *
 *     # GENERATED by HostCoverageRulesGenerator — do not edit by hand.
 *     # Source: MonitoringSubjects.hosts
 *     # Change the host list and re-run the test 'VerifyHostCoverageRulesTest'.
 *
 * Without it an edit to a generated file survives until the next generator run and then disappears
 * without a message. The spec generator marks Kotlin through `@file:Generated(by =, from =)` of
 * `it.neckar.open.annotations` instead, which [findGeneratedFileOrigin] reads as well.
 */
data class GeneratedFileMarker(
  /** The generator, not the script inside it: two entry points writing one file must produce the same bytes. */
  val by: String,

  /** The input, repository-relative for a single file, a description for a set. */
  val source: String,

  /** What to do after changing the source; may span lines. */
  val regenerateHint: String,
) {
  init {
    require(by.isNotBlank()) { "generator name must not be blank" }
    require(source.isNotBlank()) { "source must not be blank — 'do not edit' is half an instruction, the other half is where the edit belongs" }
    require(regenerateHint.isNotBlank()) { "regenerate hint must not be blank" }
  }

  /** The comment lines, each ending in a line break. */
  fun render(syntax: GeneratedFileCommentSyntax): String {
    return listOf(
      "GENERATED by $by — do not edit by hand.",
      "Source: $source",
      regenerateHint,
    )
      .flatMap { it.lines() }
      .joinToString(separator = "\n", postfix = "\n") { "${syntax.linePrefix} $it${syntax.lineSuffix}" }
  }

  /**
   * [content] with the marker in its first lines. A shebang and an XML declaration take effect on
   * line 1 only, and a YAML document start `---` keeps line 1 as well; the marker follows such a line.
   * A `---` before any other comment syntax opens front matter, which a comment would break.
   */
  fun prependTo(content: String, syntax: GeneratedFileCommentSyntax): String {
    val firstLine = content.substringBefore('\n')
    require(firstLine != "---" || syntax == GeneratedFileCommentSyntax.NumberSign) {
      "a content starting with --- takes the marker as YAML comment, not as $syntax"
    }
    if (firstLine.startsWith("#!") || firstLine.startsWith("<?xml") || firstLine == "---") {
      return firstLine + "\n" + render(syntax) + content.substringAfter('\n', missingDelimiterValue = "")
    }
    return render(syntax) + content
  }
}
